#pragma once

#include <cstring>

namespace codexbar_display::esp8266 {

enum class PairingTokenResult { Stored, KeyRequired, SaveFailed };

// New keys are 16 computer-generated bytes encoded as lowercase hex. Stored
// legacy keys are loaded separately and retain their existing validation.
template <typename Save>
PairingTokenResult StoreProvidedPairingToken(const char* token, Save save) {
  if (std::strlen(token) != 32) {
    return PairingTokenResult::KeyRequired;
  }
  for (size_t i = 0; i < 32; ++i) {
    if (!((token[i] >= '0' && token[i] <= '9') ||
          (token[i] >= 'a' && token[i] <= 'f'))) {
      return PairingTokenResult::KeyRequired;
    }
  }
  return save(token) ? PairingTokenResult::Stored : PairingTokenResult::SaveFailed;
}

}  // namespace codexbar_display::esp8266
